-- =============================================================================
-- 0003_start_lists — versioned, published start lists
--
-- The start list is generated by the rules engine (lib/competition/start-list.ts)
-- from the round's entries and previous-season rankings. Publishing stores that
-- exact list as a numbered version and moves the round to
-- start_list_published, in one transaction. The database refuses a list that
-- does not contain exactly the round's active entries, or one the rules engine
-- marked as not official (an open rule question or unusable ranking data).
-- =============================================================================

create table public.start_lists (
  id               uuid primary key default gen_random_uuid(),
  round_id         uuid not null references public.competition_rounds (id),
  version          integer not null check (version > 0),
  ruleset_version  text not null,
  -- The whole generated list: groups, heats, lanes, seeds and flags.
  payload          jsonb not null,
  published_by     uuid not null references public.profiles (id),
  published_at     timestamptz not null default now(),
  -- A newer version replaces this one (e.g. after a federation entry exception).
  superseded_at    timestamptz,
  unique (round_id, version)
);

create unique index start_lists_one_current on public.start_lists (round_id) where superseded_at is null;

-- One row per athlete per published list, so results can be checked against it.
create table public.start_list_lanes (
  start_list_id  uuid not null references public.start_lists (id),
  athlete_id     uuid not null references public.athletes (id),
  event_number   integer not null,
  category_id    text not null,
  heat_number    integer,
  lane           integer not null check (lane > 0),
  seed           integer,
  primary key (start_list_id, athlete_id)
);

create or replace function public.publish_start_list(round uuid, payload jsonb)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  cr public.competition_rounds%rowtype;
  next_version integer;
  list uuid;
  listed uuid[];
  entered uuid[];
begin
  perform public.require_federation_admin();
  select * into cr from public.competition_rounds where id = round for update;
  if not found then
    raise exception 'Round % does not exist.', round using errcode = 'P0002';
  end if;
  if cr.status <> 'registration_closed' then
    raise exception 'Close registration before publishing the start list.' using errcode = '22023';
  end if;
  if coalesce((payload ->> 'official')::boolean, false) is not true then
    raise exception 'This start list is not official: %. It cannot be published until the federation resolves it.',
      coalesce((select string_agg(b ->> 'openQuestion', ', ') from jsonb_array_elements(payload -> 'blockers') b), 'unknown reason')
      using errcode = '22023';
  end if;
  if payload ->> 'rulesetVersion' is distinct from cr.ruleset_version then
    raise exception 'The start list was generated with ruleset %, but the round uses %.',
      payload ->> 'rulesetVersion', cr.ruleset_version using errcode = '22023';
  end if;

  select coalesce(array_agg(l.athlete_id order by l.athlete_id), '{}') into listed
  from (
    select (lane -> 'entrant' ->> 'athleteId')::uuid as athlete_id
    from jsonb_array_elements(payload -> 'groups') g,
         jsonb_array_elements(g -> 'heats') h,
         jsonb_array_elements(h -> 'lanes') lane
  ) l;
  select coalesce(array_agg(athlete_id order by athlete_id), '{}') into entered
  from public.race_entries where round_id = round and status = 'active';
  if listed is distinct from entered then
    raise exception 'The start list does not match the entries for this round (% listed, % entered). Regenerate it.',
      coalesce(array_length(listed, 1), 0), coalesce(array_length(entered, 1), 0) using errcode = '22023';
  end if;
  if coalesce(array_length(entered, 1), 0) = 0 then
    raise exception 'This round has no entries.' using errcode = '22023';
  end if;

  update public.start_lists set superseded_at = now() where round_id = round and superseded_at is null;
  select coalesce(max(version), 0) + 1 into next_version from public.start_lists where round_id = round;
  insert into public.start_lists (round_id, version, ruleset_version, payload, published_by)
  values (round, next_version, cr.ruleset_version, payload, auth.uid())
  returning id into list;

  insert into public.start_list_lanes (start_list_id, athlete_id, event_number, category_id, heat_number, lane, seed)
  select list, (lane -> 'entrant' ->> 'athleteId')::uuid, (g ->> 'eventNumber')::integer, g ->> 'categoryId',
         (h ->> 'heatNumber')::integer, (lane ->> 'lane')::integer, (lane ->> 'seed')::integer
  from jsonb_array_elements(payload -> 'groups') g,
       jsonb_array_elements(g -> 'heats') h,
       jsonb_array_elements(h -> 'lanes') lane;

  -- Transaction-local marker the status guard below checks; it ends with this transaction.
  perform set_config('esf.publishing_start_list', round::text, true);
  update public.competition_rounds set status = 'start_list_published', status_changed_at = now() where id = round;
  insert into public.audit_log (actor_id, action, target_type, target_id, detail)
  values (auth.uid(), 'start_list.publish', 'competition_round', round::text,
          jsonb_build_object('version', next_version, 'athletes', array_length(entered, 1)));
  return next_version;
end;
$$;

revoke all on function public.publish_start_list(uuid, jsonb) from public, anon;
grant execute on function public.publish_start_list(uuid, jsonb) to authenticated;

-- Publishing goes through publish_start_list() only: once a list exists, the
-- generic status change may no longer move a round into start_list_published.
create or replace function public.guard_start_list_status()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if new.status = 'start_list_published' and old.status = 'registration_closed'
     and new.entry_mode = 'registration'
     and coalesce(current_setting('esf.publishing_start_list', true), '') <> new.id::text then
    raise exception 'Publish the start list from the start-list screen; it checks the list against the entries.'
      using errcode = '22023';
  end if;
  return new;
end;
$$;

create trigger competition_rounds_start_list_guard
  before update of status on public.competition_rounds
  for each row execute function public.guard_start_list_status();

alter table public.start_lists enable row level security;
alter table public.start_list_lanes enable row level security;

create policy start_lists_staff_read on public.start_lists
  for select to authenticated using (public.is_federation_staff());
-- Clubs see published start lists of the rounds they can see.
create policy start_lists_club_read on public.start_lists
  for select to authenticated using (
    public.current_club_id() is not null
    and exists (select 1 from public.competition_rounds cr where cr.id = start_lists.round_id and cr.status <> 'draft')
  );
create policy start_list_lanes_staff_read on public.start_list_lanes
  for select to authenticated using (public.is_federation_staff());
